contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newDistributor, address rewardToken, uint256 amount) public {
        require(newDistributor != address(this), "distributor must differ");

        // c was deployed by this contract, so this contract is the owner.
        require(c.owner() == address(this), "caller is owner");

        // Owner sets the distributor: state change, top-level call.
        c.setRewardDistributor(newDistributor);

        // A notify call from a non-distributor must revert.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Owner can change it back (another top-level state-changing call).
        c.setRewardDistributor(address(this));

        assert(
            c.owner() == address(this) &&
            c.rewardDistributor() == address(this) &&
            reverted
        );
    }

    receive() external payable {}
}

