contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newMigrator, address staker, uint256 amount) public {
        require(newMigrator != address(this), "migrator must differ");

        // This contract deployed c, so it is the owner and can set the migrator.
        c.setMigrator(newMigrator);

        // As a non-migrator, migrateWithdraw must revert.
        bool revertedWithdraw;
        try c.migrateWithdraw(staker, amount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // As a non-migrator, migrateStake must revert too.
        bool revertedStake;
        try c.migrateStake(address(c), amount) {
            revertedStake = false;
        } catch {
            revertedStake = true;
        }

        // Restore migrator to this contract (top-level state-changing call).
        c.setMigrator(address(this));

        assert(
            revertedWithdraw &&
            revertedStake &&
            c.migrator() == address(this) &&
            c.balanceOf(staker) == 0
        );
    }

    receive() external payable {}
}

