            try c.withdraw(amount, false) { reverted = false; } catch { reverted = true; }
        }

        // General rule: withdraw reverts iff amount > staked balance (given amount > 0).
        assert(reverted == (amount > bal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account, address rewardToken) public payable {
        require(c.balanceOf(account) == 0, "precondition: zero staked balance");

        uint256 storedClaimable = c.claimableRewards(account, rewardToken);
        uint256 computedEarned = c.earned(account, rewardToken);

        // General rule: with zero stake, the accrual term vanishes, so earned()
        // must equal the stored claimable reward for ANY account and ANY token.
        assert(computedEarned == storedClaimable);
    }

    receive() external payable {}
}
